function minePageNote(){const info=mineStateInfo(),isMultiple=info.id==='multi-active';const types=['Free','VIP','SVIP'],cards=['订阅卡','单次卡','双会员'],statuses=['续费中','已取消','生效中','已过期'];const allowedType=types;const allowedCard=info.type==='Free'?[]:isMultiple?['双会员']:['订阅卡','单次卡'];const allowedStatus=info.type==='Free'?[]:isMultiple?['生效中']:info.card==='订阅卡'?['续费中','已取消','已过期']:['生效中','已过期'];const tabs=(items,active,kind,disabled=false)=>`<div class="mine-note-tabs ${disabled?'disabled':''}">${items.map(item=>{const selected=item===active;const usable=!disabled&&((kind==='type'&&allowedType.includes(item))||(kind==='card'&&allowedCard.includes(item))||(kind==='status'&&allowedStatus.includes(item)));return `<button class="${selected?'active':''} ${usable?'':'is-disabled'}" data-mine-${kind}="${escape(item)}" ${usable?'':'disabled'}>${escape(item)}</button>`}).join('')}</div>`;return `<div class="note-context"><small>当前查看</small><b>我的 / ${info.name} · ${platform()}</b></div><div class="label">会员状态</div><div class="mine-status-tabs"><div class="mine-tab-group"><small>会员类型</small>${tabs(types,info.type,'type')}</div><div class="mine-tab-group"><small>商品类型</small>${tabs(cards,info.card,'card',info.type==='Free')}</div><div class="mine-tab-group"><small>权益状态</small>${tabs(statuses,info.status,'status',info.type==='Free')}</div></div><div class="label">页面完整说明</div><div class="copy"><strong>${page().pageNote.description}</strong><br>进入路径：${page().pageNote.path}<br>当前状态：${info.name}。切换状态标签后，左侧预览和当前规则同步更新。</div><div class="label">会员卡片</div><div class="copy state-copy"><strong>${info.rule}</strong></div>`}

function pageNote(){if(state.pageId==='mine'){const info=mineStateInfo(),group=info.status==='续费中'&&info.type==='VIP',primary=group?'进群':info.status==='续费中'?'终身权益':info.status==='已取消'?'恢复续费':info.status==='已过期'?'恢复权益':'开通会员',source=info.type==='Free'?'':`<span class="mine-primary-flow-note">主按钮「${primary}」${group?'进入交流群入口。':'点击后直接进入付费页，不展示中间弹窗，并自动选中对应商品。'}</span>`;return `<div class="mine-requirements-layout">${source}${minePageNote()}</div>`}const p=page(),s=pageState();return `<div class="note-context"><small>当前查看</small><b>${label()} · ${platform()}</b></div><div class="label">页面完整说明</div><div class="copy"><strong>${p.pageNote.description}</strong><br>进入路径：${p.pageNote.path}<br>当前状态：${s.name}。切换状态后，预览和状态规则同步更新。<div class="scope">${scopeTags(['页面级说明'])}</div></div><div class="label">页面模块</div><div class="blocks">${p.pageNote.modules.map((m,i)=>`<div class="block"><i class="number">${i+1}</i>${m}</div>`).join('')}</div><div class="label">当前状态规则</div><div class="copy state-copy"><strong>${s.stateNote.rule}</strong><br>这部分只在「${s.name}」下生效；切换后会自动替换。</div>`}
